reference.setup:
{
    run_fisher <- function(m) {
        t <- fisher.test(m)
        list(p = t$p.value, n = sum(m), odds_ratio = if (is.null(t$estimate)) NA_real_ else unname(t$estimate), 
            or_lower = if (is.null(t$conf.int)) NA_real_ else t$conf.int[1], or_upper = if (is.null(t$conf.int)) NA_real_ else t$conf.int[2])
    }
}
